insert into bbpac_tracker_items (sheet, sort_order, title, link, fields) values ('funders', 12, 'Field Foundation — A Road Together (ART)', 'https://fieldfoundation.org/grantmaking/a-road-together/', '[{"label": "What it funds", "value": "Multi-year UNRESTRICTED general operating for small/mid Chicago arts orgs, prioritizing South and West Sides."}, {"label": "Amount", "value": "$10,000-$100,000/yr, 3-year awards"}, {"label": "Status", "value": "BLOCKED"}, {"label": "Eligibility reality for Ras Tafari Inc.", "value": "$25,000 OPERATING BUDGET FLOOR is the barrier, not years. Once you clear $25k, this is an outstanding fit — South Side priority, participatory panel of Chicago artists. Co-funded by MacArthur."}, {"label": "Deadline", "value": "Window currently closed. 2026 cohort announced fall 2026."}, {"label": "Contact", "value": "Impact House, 200 W Madison St"}]'::jsonb) on conflict (sheet, sort_order) do update set title = excluded.title, link = excluded.link, fields = excluded.fields;
insert into bbpac_tracker_items (sheet, sort_order, title, link, fields) values ('funders', 13, 'NEA — Grants for Arts Projects / Our Town', 'https://www.arts.gov/grants/grants-for-arts-projects', '[{"label": "What it funds", "value": "Arts projects and creative placemaking."}, {"label": "Amount", "value": "$10,000-$100,000, 1:1 match required"}, {"label": "Status", "value": "BLOCKED"}, {"label": "Eligibility reality for Ras Tafari Inc.", "value": "HARD DISQUALIFIER: 5 completed years of arts programming before the deadline, plus $20,000 operating expenses in the last completed fiscal year. Ineligible until roughly 2031. A fiscal sponsor does NOT cure this."}, {"label": "Deadline", "value": "GAP 2 Part 1 was Jul 9, 2026."}, {"label": "Contact", "value": "via arts.gov"}]'::jsonb) on conflict (sheet, sort_order) do update set title = excluded.title, link = excluded.link, fields = excluded.fields;
insert into bbpac_tracker_items (sheet, sort_order, title, link, fields) values ('funders', 14, 'Illinois Arts Council — General Operating Support', 'https://arts.illinois.gov/granting-opportunities/grants-programs/general-operating-support.html', '[{"label": "What it funds", "value": "Unrestricted operating support, awarded by formula."}, {"label": "Amount", "value": "Formula-based; +$4,500 youth employment add-on"}, {"label": "Status", "value": "CHECK"}, {"label": "Eligibility reality for Ras Tafari Inc.", "value": "Needs 12 months of public arts programming. You reach that in June 2027 — borderline for a March 2027 deadline. DOCUMENT PROGRAMMING CONTINUOUSLY FROM JUNE 2026. Also needs GATA pre-qualification, which takes weeks — start it now regardless."}, {"label": "Deadline", "value": "FY27 closed Mar 18, 2026."}, {"label": "Contact", "value": "iac.info@illinois.gov"}]'::jsonb) on conflict (sheet, sort_order) do update set title = excluded.title, link = excluded.link, fields = excluded.fields;
